#include <cmath>
using namespace std;

int main()
{
    int n;
    cin >> n;

    if (n == 4)
        cout << 1;
    else if (n == 7)
        cout << 2;
    else
    {
        int x = n, k = 0, r = 0, f;

        while (x != 0)
        {
            k++;
            x /= 10;
        }

        if (n / static_cast<int>(pow(10, k - 1)) == 4)
            r = static_cast<int>(pow(2, k)) - 1;

        if (n / static_cast<int>(pow(10, k - 1)) == 7)
            r = static_cast<int>(pow(2, k)) +
                static_cast<int>(pow(2, k - 1)) - 1;

        while (k > 1)
        {
            n %= static_cast<int>(pow(10, k - 1));
            f = n / static_cast<int>(pow(10, k - 2));

            if (f == 7)
                r += static_cast<int>(pow(2, k - 2));

            k--;
        }

        cout << r;
    }

    return 0;
}

